import{_ as a,o as l,c as o,j as e,a as r}from"./chunks/framework.ETupdKIa.js";const C=JSON.parse('{"title":"UCP","description":"","frontmatter":{"title":"UCP","date":"2026-02-11T00:00:00.000Z","status":"published"},"headers":[],"relativePath":"til/決済/20260211_UCP.md","filePath":"til/決済/20260211_UCP.md"}'),n={name:"til/決済/20260211_UCP.md"};function s(c,t,i,P,p,_){return l(),o("div",null,[...t[0]||(t[0]=[e("h1",{id:"_20260211-ucp",tabindex:"-1"},[r("20260211_UCP "),e("a",{class:"header-anchor",href:"#_20260211-ucp","aria-label":"Permalink to “20260211_UCP”"},"​")],-1),e("p",null,"Universal Commerce Protocolの略で、Googleが主導で策定しているエージェンティックコーマスの標準仕様のこと。",-1),e("p",null,"前提として、エージェンティックコマースとは、これまで人間がブラウザ上で行なってきた「商品を検索し、カートに入れ、決済を行う」という一連の流れを、AIエージェントが行うことを指す。AIエージェントは画面操作ではなくECサイトが提供するAPIを使用して購入フローを進めるが、標準仕様がない場合、各AIエージェントは各ECサイトと接続するために個別の実装を行う必要がある。そこで、AIエージェント-ECサイト間のコミュニケーションに関する共通仕様を定めようという取り組みがUCPであり、各ECサイトはUCPに則ってAIエージェント用の入り口となるエンドポイント「./well-known/ucp」を用意し、各AIエージェントはそのエンドポイントから各ECサイトへアクセス・購入アクションを行う。",-1),e("p",null,"AIエージェントは「./well-known/ucp」にアクセスすることで、そのECサイトが提供するAPI一覧（商品検索用API、カート登録API、チェックアウトAPI）などを取得することができ、ここで取得したAPIの情報をもとに、購入フローを進めていくことができる。",-1)])])}const u=a(n,[["render",s]]);export{C as __pageData,u as default};
